9	func TestNewRootCmdHelp(t *testing.T) {
10		root := NewRootCmd()
11		var buf bytes.Buffer
12		root.SetOut(&buf)
13		root.SetErr(&buf)
14		root.SetArgs([]string{"--help"})
15		if err := root.Execute(); err != nil {
16			t.Fatalf("execute: %v", err)
17		}
18		out := buf.String()
19		for _, want := range []string{"birdseye", "--crow-url", "--timeout"} {
20			if !strings.Contains(out, want) {
21				t.Errorf("help output missing %q\n---\n%s", want, out)
22			}
23		}
24	}
25	
26	func TestNewRootCmdDefaults(t *testing.T) {
27		root := NewRootCmd()
28		if got, _ := root.PersistentFlags().GetString("crow-url"); got != "https://crow.infrastructure.immuta.io" {
29			t.Errorf("crow-url default = %q", got)
30		}
31	}
